  var e={ t0:B.t0, t1:t1, from:B.from, to:nearName(B.last), dist:Math.round(B.dist), alt:B.maxAlt==null?null:Math.round(B.maxAlt*FT), gs:Math.round(B.maxGs*1.94384), ac:(P.ac && P.ac.name)||"" };
