  var s={ id:id, name:e.from+" → "+e.to, categoryName:"ULM / Avion", activityType:"ulm", milieu:"air", startedAt:new Date(t0).toISOString(), durationSec:dur, distanceM:e.dist, avgSpeedKmh:+(e.dist/dur*3.6).toFixed(1), maxSpeedKmh:+(B.maxGs*3.6).toFixed(1),
    maxAltM:B.maxAlt==null?0:Math.round(B.maxAlt), firstLat:pts[0].lat, firstLon:pts[0].lon, thumbnailUrl:null, source:"phone", points:pts };
  var arr=[]; try{ arr=JSON.parse(localStorage.getItem("lf_phone_sessions")||"[]")||[]; }catch(x){} arr=arr.filter(function(x){ return x && x.id!==id; }); arr.unshift(s); if(arr.length>100) arr=arr.slice(0,100);
