function flySess(sid){ try{ var a=JSON.parse(localStorage.getItem("lf_phone_sessions")||"[]")||[]; for(var i=0;i<a.length;i++){ if(a[i] && String(a[i].id)===String(sid)) return a[i]; } }catch(e){} return null; }
